<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Csrf;use App\Core\Database;use App\Services\DanceCupJudgingPanelService;use App\Services\DanceCupScoringService;
Auth::requireAdmin();$test=(string)($_GET['data_mode']??$_POST['data_mode']??'')==='test';if($test&&!Auth::isSuperAdmin()){http_response_code(403);exit('Super Admin access required.');}
$pdo=Database::connection();DanceCupScoringService::ensureWorkspaceTables($pdo,$test);DanceCupJudgingPanelService::ensureTables($pdo,$test);$p=DanceCupJudgingPanelService::prefix($test);$t=DanceCupScoringService::tables($test);$suffix=$test?'&data_mode=test':'';$notice='';$error='';
try{
 if($_SERVER['REQUEST_METHOD']==='POST'){
  if(!Csrf::verify($_POST['_csrf']??null))throw new RuntimeException('Invalid security token.');$action=(string)($_POST['action']??'');
  if($action==='create_panel'){$panelId=DanceCupJudgingPanelService::create($pdo,(int)($_POST['event_id']??0),(string)($_POST['panel_name']??''),(string)($_POST['discipline']??''),(array)($_POST['category_id']??[]),(int)(Auth::user()['id']??0)?:null,$test);header('Location: panels.php?panel_id='.$panelId.$suffix,true,303);exit;}
  if($action==='add_judge'){DanceCupJudgingPanelService::addJudge($pdo,(int)($_POST['panel_id']??0),(int)($_POST['judge_id']??0)?:null,(string)($_POST['judge_name']??''),!empty($_POST['is_chief']),$test);$notice='Judge added to every category in this panel. One panel link is ready.';}
  if($action==='make_chief'){DanceCupJudgingPanelService::setChief($pdo,(int)($_POST['panel_id']??0),(int)($_POST['panel_judge_id']??0),$test);$notice='Chief Judge updated across every panel category.';}
  if($action==='remove_judge'){DanceCupJudgingPanelService::removeJudge($pdo,(int)($_POST['panel_id']??0),(int)($_POST['panel_judge_id']??0),$test);$notice='Judge removed from every category in this panel.';}
  if($action==='regenerate'){$pdo->prepare("UPDATE {$p}_judging_panel_judges SET access_token=:token WHERE id=:judge")->execute(['token'=>bin2hex(random_bytes(32)),'judge'=>(int)($_POST['panel_judge_id']??0)]);$notice='Panel judge link regenerated.';}
 }
}catch(Throwable $e){$error=$e->getMessage();}
$events=[];$categories=[];$panels=[];$panel=null;$panelCategories=[];$panelJudges=[];
try{$events=$pdo->query("SELECT e.id,e.name,e.event_date,COUNT(c.id) category_count FROM {$t['events']} e JOIN {$t['competitions']} c ON c.event_id=e.id AND c.scoring_mode='automatic' WHERE e.status<>'archived' GROUP BY e.id,e.name,e.event_date ORDER BY e.event_date DESC,e.id DESC")->fetchAll();}catch(Throwable $e){$error=$error?:'Judging panel data could not be loaded: '.$e->getMessage();}
$eventId=(int)($_GET['event_id']??$_POST['event_id']??($events[0]['id']??0));$panelId=(int)($_GET['panel_id']??$_POST['panel_id']??0);
try{
 if($eventId){$q=$pdo->prepare("SELECT c.id,c.category_name,c.dance_style,c.entry_type,c.competition_level,c.round_name,c.status,pc.panel_id,p.panel_name FROM {$t['competitions']} c LEFT JOIN {$p}_judging_panel_categories pc ON pc.competition_id=c.id LEFT JOIN {$p}_judging_panels p ON p.id=pc.panel_id AND p.status='active' WHERE c.event_id=:event AND c.scoring_mode='automatic' ORDER BY c.dance_style,c.category_name,c.id");$q->execute(['event'=>$eventId]);$categories=$q->fetchAll();}
 $panels=$pdo->query("SELECT p.*,e.name event_name,(SELECT COUNT(*) FROM {$p}_judging_panel_categories pc WHERE pc.panel_id=p.id) category_count,(SELECT COUNT(*) FROM {$p}_judging_panel_judges pj WHERE pj.panel_id=p.id) judge_count FROM {$p}_judging_panels p JOIN {$t['events']} e ON e.id=p.event_id WHERE p.status='active' ORDER BY e.event_date DESC,p.id DESC")->fetchAll();
 if($panelId){$q=$pdo->prepare("SELECT p.*,e.name event_name FROM {$p}_judging_panels p JOIN {$t['events']} e ON e.id=p.event_id WHERE p.id=:panel");$q->execute(['panel'=>$panelId]);$panel=$q->fetch();if($panel){$q=$pdo->prepare("SELECT c.*,pc.sort_order FROM {$p}_judging_panel_categories pc JOIN {$t['competitions']} c ON c.id=pc.competition_id WHERE pc.panel_id=:panel ORDER BY pc.sort_order,c.id");$q->execute(['panel'=>$panelId]);$panelCategories=$q->fetchAll();$q=$pdo->prepare("SELECT * FROM {$p}_judging_panel_judges WHERE panel_id=:panel ORDER BY is_chief DESC,judge_order,id");$q->execute(['panel'=>$panelId]);$panelJudges=$q->fetchAll();$submitted=$pdo->prepare("SELECT COUNT(DISTINCT pc.competition_id) FROM {$p}_judging_panel_categories pc JOIN {$p}_judges j ON j.competition_id=pc.competition_id JOIN {$p}_judge_sessions s ON s.competition_id=pc.competition_id AND s.judge_assignment_id=j.id WHERE pc.panel_id=:panel AND ((:judge_id IS NOT NULL AND j.judge_id=:judge_id_match) OR (:judge_id_null IS NULL AND j.judge_name=:judge_name)) AND s.status='submitted'");foreach($panelJudges as &$panelJudge){$judgeId=$panelJudge['judge_id']!==null?(int)$panelJudge['judge_id']:null;$submitted->execute(['panel'=>$panelId,'judge_id'=>$judgeId,'judge_id_match'=>$judgeId,'judge_id_null'=>$judgeId,'judge_name'=>$panelJudge['judge_name']]);$panelJudge['submitted_categories']=(int)$submitted->fetchColumn();}unset($panelJudge);}}
}catch(Throwable $e){$error=$error?:'Judging panel data could not be loaded: '.$e->getMessage();}
$csrf=Csrf::token();
ob_start(static function(string $html):string{$script=<<<'HTML'
<script>
document.querySelectorAll('form input[name="panel_judge_id"]').forEach(input=>{
 const form=input.form;if(!form||!form.querySelector('button[value="regenerate"]'))return;
 const card=form.closest('article');
 if(card&&!card.textContent.includes('★ Chief')){const chief=document.createElement('button');chief.className='btn btn-sm btn-outline-warning ms-1';chief.name='action';chief.value='make_chief';chief.textContent='Make Chief';form.appendChild(chief);}
 const remove=document.createElement('button');remove.className='btn btn-sm btn-outline-danger ms-1';remove.name='action';remove.value='remove_judge';remove.textContent='Remove';remove.addEventListener('click',event=>{if(!confirm('Remove this judge from every category in the panel?'))event.preventDefault()});form.appendChild(remove);
});
</script>
HTML;return str_replace('</body>',$script.'</body>',$html);});
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Judging Panels | Dance Cup</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../../public/css/scoring-premium.css?v=459" rel="stylesheet"><script defer src="../../public/assets/js/bdc-theme.js?v=420"></script><script defer src="../../public/js/dance-cup-directory.js?v=426"></script><style>body{background:#eef3f9}.panel-hero{border:0;border-radius:24px;background:linear-gradient(125deg,#101d35,#19396d 58%,#621d3e);color:#fff}.panel-card{border:1px solid #dae3ef;border-radius:18px;box-shadow:0 12px 30px rgba(20,38,65,.08)}.category-choice{display:grid;grid-template-columns:auto 1fr auto;gap:12px;align-items:center;padding:12px;border:1px solid #dde5ef;border-radius:12px}.panel-link{display:grid;grid-template-columns:1fr auto auto;gap:8px}.dc-directory-field{position:relative}@media(max-width:650px){.panel-link{grid-template-columns:1fr 1fr}.panel-link input{grid-column:1/-1}.category-choice{grid-template-columns:auto 1fr}.category-choice .badge{grid-column:2}}</style></head><body><nav class="navbar navbar-dark bg-dark"><div class="container-fluid"><a class="navbar-brand" href="workflow.php?workflow=automatic<?=$suffix?>">Dance Cup Automatic</a><a class="btn btn-outline-light btn-sm" href="../">Dashboard</a></div></nav><main class="container py-4" style="max-width:1250px"><section class="panel-hero p-4 p-lg-5 mb-4"><span class="badge text-bg-warning"><?=$test?'TEST · ':''?>JUDGING PANELS</span><h1 class="h2 mt-2">One judge link for multiple categories</h1><p class="mb-0 opacity-75">Group related categories while keeping contestants, marks, ranking, projection and approval fully independent.</p></section><?php if($notice):?><div class="alert alert-success"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?>
<?php if($panel):?><div class="d-flex justify-content-between gap-2 flex-wrap mb-3"><div><span class="badge text-bg-primary"><?=e(ucwords(str_replace('_',' ',$panel['discipline'])))?></span><h2 class="h3 mt-2 mb-1"><?=e($panel['panel_name'])?></h2><p class="text-muted mb-0"><?=e($panel['event_name'])?> · <?=count($panelCategories)?> categories</p></div><a class="btn btn-outline-secondary align-self-start" href="panels.php?event_id=<?=(int)$panel['event_id']?><?=$suffix?>">← All Panels</a></div><div class="row g-4"><div class="col-lg-5"><section class="card panel-card"><div class="card-body p-4"><h3 class="h5">Included Categories</h3><div class="d-grid gap-2 mt-3"><?php foreach($panelCategories as $c):?><div class="category-choice"><span class="badge text-bg-primary"><?=(int)$c['sort_order']?></span><div><strong><?=e($c['category_name'])?></strong><small class="d-block text-muted"><?=e(ucwords(str_replace('_',' ',$c['dance_style'])))?> · <?=e(ucfirst($c['round_name']))?></small></div><span class="badge text-bg-light border"><?=e(ucfirst($c['status']))?></span></div><?php endforeach;?></div></div></section></div><div class="col-lg-7"><section class="card panel-card"><div class="card-body p-4"><h3 class="h5">Panel Judges</h3><form method="post" class="row g-2 mt-2 mb-4"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="data_mode" value="<?=$test?'test':'real'?>"><input type="hidden" name="panel_id" value="<?=$panelId?>"><input type="hidden" name="action" value="add_judge"><div class="col-md"><div class="dc-directory-field"><input class="form-control" name="judge_name" placeholder="Type judge name or Judge ID" data-directory-type="judge" data-directory-target="dcPanelJudgeId" autocomplete="off" required><input id="dcPanelJudgeId" type="hidden" name="judge_id"><span class="dc-directory-hint">Choose a Judge Database suggestion when available.</span></div></div><div class="col-auto form-check pt-2"><input class="form-check-input" type="checkbox" name="is_chief" id="panelChief"><label class="form-check-label" for="panelChief">Chief</label></div><div class="col-auto"><button class="btn btn-primary">Add to Panel</button></div></form><?php foreach($panelJudges as $j):$link=url('admin/dance-cup/judge-scoring.php?token='.$j['access_token'].($test?'&data_mode=test':''));?><article class="border rounded-3 p-3 mb-2"><div class="d-flex justify-content-between gap-2 mb-2"><strong>J<?=(int)$j['judge_order']?> · <?=e($j['judge_name'])?><?=$j['is_chief']?' · ★ Chief':''?></strong><span class="badge text-bg-success"><?=(int)$j['submitted_categories']?> / <?=count($panelCategories)?> submitted</span></div><div class="panel-link"><input id="panelLink<?=(int)$j['id']?>" class="form-control" readonly value="<?=e($link)?>"><button type="button" class="btn btn-outline-primary" data-copy="panelLink<?=(int)$j['id']?>">Copy</button><a class="btn btn-primary" target="_blank" rel="noopener" href="<?=e($link)?>">Open</a></div><form method="post" class="mt-2"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="data_mode" value="<?=$test?'test':'real'?>"><input type="hidden" name="panel_id" value="<?=$panelId?>"><input type="hidden" name="panel_judge_id" value="<?=(int)$j['id']?>"><button class="btn btn-sm btn-outline-secondary" name="action" value="regenerate" onclick="return confirm('Regenerate this panel link?')">Regenerate</button></form></article><?php endforeach;?><?php if(!$panelJudges):?><div class="alert alert-warning mb-0">Add the panel judges. Every judge will receive one link covering all categories above.</div><?php endif;?></div></section></div></div>
<?php else:?><div class="row g-4"><div class="col-lg-7"><section class="card panel-card"><div class="card-body p-4"><h2 class="h4">Create Judging Panel</h2><form method="get" class="mb-3"><input type="hidden" name="data_mode" value="<?=$test?'test':'real'?>"><label class="form-label">Dance Cup Event</label><select class="form-select" name="event_id" onchange="this.form.submit()"><?php foreach($events as $event):?><option value="<?=(int)$event['id']?>" <?=$eventId===(int)$event['id']?'selected':''?>><?=e($event['name'])?> · <?=(int)$event['category_count']?> Automatic categories</option><?php endforeach;?></select></form><form method="post"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="data_mode" value="<?=$test?'test':'real'?>"><input type="hidden" name="action" value="create_panel"><input type="hidden" name="event_id" value="<?=$eventId?>"><div class="row g-2 mb-3"><div class="col-md-7"><label class="form-label">Panel name</label><input class="form-control" name="panel_name" placeholder="Example: Salsa Solo Panel" required></div><div class="col-md-5"><label class="form-label">Discipline</label><select class="form-select" name="discipline"><option value="salsa">Salsa</option><option value="bachata">Bachata</option><option value="team">Team Choreography</option><option value="pro_am">Pro Am</option><option value="other">Other</option></select></div></div><label class="form-label">Categories using this judge panel</label><div class="d-grid gap-2 mb-3"><?php foreach($categories as $c):?><label class="category-choice <?=!empty($c['panel_id'])?'opacity-50':''?>"><input class="form-check-input" type="checkbox" name="category_id[]" value="<?=(int)$c['id']?>" <?=!empty($c['panel_id'])?'disabled':''?>><div><strong><?=e($c['category_name'])?></strong><small class="d-block text-muted"><?=e(ucwords(str_replace('_',' ',$c['dance_style'])))?> · <?=e(ucwords(str_replace('_',' ',$c['entry_type'])))?> · <?=e(ucwords(str_replace('_',' ',$c['competition_level'])))?></small></div><?php if(!empty($c['panel_id'])):?><span class="badge text-bg-secondary">Already in <?=e($c['panel_name'])?></span><?php endif;?></label><?php endforeach;?></div><button class="btn btn-primary btn-lg">Create Panel &amp; Assign Judges</button></form></div></section></div><div class="col-lg-5"><section class="card panel-card"><div class="card-body p-4"><h2 class="h4">Active Panels</h2><div class="d-grid gap-2 mt-3"><?php foreach($panels as $row):?><a class="text-decoration-none border rounded-3 p-3" href="panels.php?panel_id=<?=(int)$row['id']?><?=$suffix?>"><strong class="d-block"><?=e($row['panel_name'])?></strong><small class="text-muted"><?=e($row['event_name'])?> · <?=(int)$row['category_count']?> categories · <?=(int)$row['judge_count']?> judges</small></a><?php endforeach;?><?php if(!$panels):?><p class="text-muted">No judging panels created yet.</p><?php endif;?></div></div></section></div></div><?php endif;?></main><script>document.addEventListener('click',async e=>{const b=e.target.closest('[data-copy]');if(!b)return;const i=document.getElementById(b.dataset.copy);try{await navigator.clipboard.writeText(i.value)}catch{x=i;i.select();document.execCommand('copy')}b.textContent='Copied';setTimeout(()=>b.textContent='Copy',1200)})</script></body></html>
